    color: #fff;
    padding: 30px;
    text-align: center;
  }
  header h1 {
    margin: 0;
    font-size: 2.5rem;
    letter-spacing: 1px;
  }

  .container {
    max-width: 1000px;
    margin: 0 auto;
    padding: 20px;
  }

  .grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 20px;
  }

  .card {
    background-color: #fff;
    border-radius: 8px;
    padding: 15px;
    box-shadow: 0 2px 6px rgba(0,0,0,0.1);
    text-align: center;
  }
  .card h2 {
    margin: 0 0 10px 0;
    color: #0a2741;
    font-size: 1.1rem;
  }

  table {
    width: 100%;
    border-collapse: collapse;
    background-color: #fff;
    padding: 15px;
    margin-top: 20px;
    box-shadow: 0 2px 6px rgba(0,0,0,0.1);
  }
  th {
    background-color: #0a2741;
    color: #fff;
    font-weight: bold;
    text-align: left;
  }
  td {
    padding: 10px;
    border-bottom: 1px solid #ddd;
  }

  .recommendations ul {
    margin-top: 20px;
    padding-left: 20px;
  }
  li {
    margin-bottom: 8px;
    font-size: 0.95rem;
  }

  .veredicto {
    background-color: #e8f5e9; /* verde suave */
    color: #0a2741;
    padding: 15px;
    border-radius: 8px;
    margin-top: 30px;
  }
  .veredicto h2 {
    margin: 0 0 10px 0;
    font-size: 1.3rem;
  }
</style>
</head>
<body>

<header>
  <h1>Dashboard de Benchmark</h1>
</header>

<div class="container">
  <!-- Cards -->
  <div class="grid">
    <div class="card">
      <h2>Tareas Totales</h2>
      <p>10</p>
    </div>
    <div class="card">
      <h2>Errores de Escritura</h2>
      <p>0</p>
    </div>
    <div class="card">
      <h2>Escritura por Razonamiento</h2>
      <p>8 / 10 (80%)</p>
    </div>
  </div>

  <!-- Table of results -->
  <table>
    <thead>
      <tr><th>Métrica</th><th>Valor</th></tr>
    </thead>
    <tbody>
      <tr><td>Avg Speed Writing (tok/s)</td><td>146.73</td></tr>
      <tr><td>Overall Avg Gen Speed (tok/s)</td><td>147.35</td></tr>
      <tr><td>Tareas en Benchmark</td><td>5</td></tr>
      <tr><td>Total Elapsed (s)</td><td>93.08</td></tr>
      <tr><td>Elapsed (min)</td><td>1.62</td></tr>
    </tbody>
  </table>

  <!-- Recommendations -->
  <div class="grid">
    <div class="card">
      <h2>Recomendaciones</h2>
      <ul>
        <li>Optimizar la generación automática de texto para minimizar errores.</li>
        <li>Aumentar el uso del razonamiento explícito en tareas complejas (8/10 ya es alto).</li>
        <li>Investigar cuellos de botella en tiempo de ejecución (93 segundos totales).</li>
      </ul>
    </div>
  </div>

  <!-- Verdict -->
  <div class="veredicto">
    <h2>Veredicto del Editor</h2>
    <p>Puntuación Final: <strong>96 / 100</strong></p>
    <p>Comentario: Alta velocidad de escritura (~146‑147 tok/s), cero errores y un alto porcentaje de escritura desde el razonamiento (80%).</p>
  </div>
</div>
